import{_ as n,C as l,o as i,c as s,a2 as a,b as o,w as t,a as c,E as d,a3 as u}from"./chunks/framework.XaTYfhfj.js";const v=JSON.parse('{"title":"14.9 Reliability, Fault Tolerance & Resilience Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.9-reliability-and-resilience.md","filePath":"system-design/14.9-reliability-and-resilience.md"}'),h={name:"system-design/14.9-reliability-and-resilience.md"};function m(p,e,g,f,b,k){const r=l("Mermaid");return i(),s("div",null,[e[1]||(e[1]=a('<h1 id="_14-9-reliability-fault-tolerance-resilience-engineering" tabindex="-1">14.9 Reliability, Fault Tolerance &amp; Resilience Engineering <a class="header-anchor" href="#_14-9-reliability-fault-tolerance-resilience-engineering" aria-label="Permalink to &quot;14.9 Reliability, Fault Tolerance &amp; Resilience Engineering&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Reliability engineering ensures a system continues operating correctly even when infrastructure, networks, or upstream third-party dependencies fail. Resilience patterns prevent isolated errors from cascading into catastrophic system-wide outages.</p><hr><h2 id="_2-resilience-patterns-implemented-in-truthguard" tabindex="-1">2. Resilience Patterns Implemented in TruthGuard <a class="header-anchor" href="#_2-resilience-patterns-implemented-in-truthguard" aria-label="Permalink to &quot;2. Resilience Patterns Implemented in TruthGuard&quot;">​</a></h2>',5)),(i(),o(u,null,{default:t(()=>[d(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Request%5BUser%20Request%5D%20--%3E%20Breaker%7BCircuit%20Breaker%20State%7D%0A%20%20%20%20%0A%20%20%20%20Breaker%20--%3E%7CClosed%20(Normal)%7C%20CallAI%5BInvoke%20Upstream%20AI%20API%5D%0A%20%20%20%20Breaker%20--%3E%7COpen%20(Tripped)%7C%20FallbackHeuristic%5BFallback%3A%20Regex%20%26%20Local%20Heuristic%20Engine%5D%0A%20%20%20%20%0A%20%20%20%20CallAI%20--%3E%7CTimeout%20%3E%203s%20%2F%20500%20Error%7C%20RecordFail%5BRecord%20Failure%5D%0A%20%20%20%20RecordFail%20--%3E%20ThresholdCheck%7BFailures%20%3E%205%20in%2010s%3F%7D%0A%20%20%20%20ThresholdCheck%20--%3E%7CYes%7C%20TripBreaker%5BTrip%20Circuit%20Breaker%20to%20Open%5D%0A%20%20%20%20ThresholdCheck%20--%3E%7CNo%7C%20RetryBackoff%5BRetry%20with%20Exponential%20Backoff%20%26%20Jitter%5D%0A%20%20%20%20%0A%20%20%20%20TripBreaker%20--%3E%20FallbackHeuristic%0A%20%20%20%20FallbackHeuristic%20--%3E%20ReturnSafeResult%5BReturn%20Safe%20Baseline%20Verdict%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="_1-circuit-breaker-pattern" tabindex="-1">1. Circuit Breaker Pattern <a class="header-anchor" href="#_1-circuit-breaker-pattern" aria-label="Permalink to &quot;1. Circuit Breaker Pattern&quot;">​</a></h3><ul><li><strong>Problem</strong>: If an upstream AI inference provider experiences an outage, requests hang for 15 seconds before timing out, tying up browser worker threads and gateway connections.</li><li><strong>Mitigation</strong>: A circuit breaker trips after 5 consecutive failures within a 10-second window. Once tripped, subsequent requests bypass the upstream API immediately, returning deterministic heuristic fallback verdicts while periodically testing health via a half-open state.</li></ul><h3 id="_2-retries-with-exponential-backoff-full-jitter" tabindex="-1">2. Retries with Exponential Backoff &amp; Full Jitter <a class="header-anchor" href="#_2-retries-with-exponential-backoff-full-jitter" aria-label="Permalink to &quot;2. Retries with Exponential Backoff &amp; Full Jitter&quot;">​</a></h3><ul><li><strong>Formula</strong>: $$t_{\\text{wait}} = \\min(t_{\\text{max}}, t_{\\text{base}} \\times 2^{\\text{attempt}}) \\times \\text{random}(0, 1)$$</li><li>Prevents the &quot;thundering herd&quot; effect where hundreds of failed requests retry at the identical millisecond interval.</li></ul><h3 id="_3-graceful-degradation" tabindex="-1">3. Graceful Degradation <a class="header-anchor" href="#_3-graceful-degradation" aria-label="Permalink to &quot;3. Graceful Degradation&quot;">​</a></h3><ul><li>In [<code>camara-temper/src/lib/fileAnalyzer.ts:L165-174</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/camara-temper/src/lib/fileAnalyzer.ts#L165-L174), if binary EXIF parsing fails due to non-image formats or header corruption, the system does not crash; it logs a warning flag, applies a baseline score (50), and continues rendering raw file metrics.</li></ul><hr><h2 id="_3-availability-targets-sli-slo-sla" tabindex="-1">3. Availability Targets: SLI, SLO &amp; SLA <a class="header-anchor" href="#_3-availability-targets-sli-slo-sla" aria-label="Permalink to &quot;3. Availability Targets: SLI, SLO &amp; SLA&quot;">​</a></h2><ul><li><strong>Service Level Indicator (SLI)</strong>: Percentage of successful forensic API invocations completed with latency &lt; 2.0 seconds.</li><li><strong>Service Level Objective (SLO)</strong>: 99.9% of valid requests return within 2.0s over any rolling 30-day window.</li><li><strong>Service Level Agreement (SLA)</strong>: 99.5% monthly availability, backed by financial service credits.</li><li><strong>Disaster Recovery</strong>: <ul><li><strong>Recovery Point Objective (RPO)</strong>: &lt; 5 minutes (via automated WAL archiving in PostgreSQL).</li><li><strong>Recovery Time Objective (RTO)</strong>: &lt; 15 minutes (via multi-region automated database failover).</li></ul></li></ul><hr><h2 id="_4-30-second-spoken-interview-answer" tabindex="-1">4. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_4-30-second-spoken-interview-answer" aria-label="Permalink to &quot;4. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;To guarantee 99.9% availability, we implement circuit breakers and graceful degradation across our integration boundaries. If an upstream AI provider experiences an outage, our circuit breaker trips after five failures, falling back immediately to client-side heuristic pattern matching rather than hanging.</p><p>Furthermore, all transient network retries utilize exponential backoff with full jitter to avoid overwhelming our gateways after recovery.&quot;</p></blockquote>',12))])}const y=n(h,[["render",m]]);export{v as __pageData,y as default};
